import pathlib
import pytest

from rsbio_seq import SeqReaderIndexed, Sequence

dir = pathlib.Path(__file__).parent


def test_read_fa():
    seqs = SeqReaderIndexed(
        dir.joinpath("../test_data/reads_indexable.fa").as_posix(),
        dir.joinpath("../test_data/reads_indexable.fa.fai").as_posix(),
    )
    seq: Sequence = seqs["Record_1"]
    assert seq.id == "Record_1"
    assert seq.desc == "Description 1"
    assert (
        seq.seq
        == "GGGTGATGGCCGCTGCCGATGGCGTCAAATCCCACCAAGTTACCCTTAACAACTTAAGGGTTTTCAAATAGATGCATGCTGATCGATCGTACGATCGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTACCGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGAT"
    )

    seq: Sequence = seqs["Record_2"]
    assert seq.id == "Record_2"
    assert seq.desc == "Description 2"
    assert (
        seq.seq
        == "GTTCAGGGATACGACGTTTGTATTTTAAGAATCCAAGTTACCCTTAACAACTTAAGGGTTTTCAAATAGATGAAGCAGAAGTCGATGATAATACGCGTCGTTTTATCATCAAGTTACCCTTAACAACTTAAGGGTTTTCA"
    )

    assert "Record_1" in seqs
    assert "DoesNotExist" not in seqs

    with pytest.raises(KeyError):
        seq: Sequence = seqs["DoesNotExist"]


def test_read_fa_gz():
    seqs = SeqReaderIndexed(
        dir.joinpath("../test_data/reads_indexable.fa.gz").as_posix(),
        dir.joinpath("../test_data/reads_indexable.fa.gz.fai").as_posix(),
        dir.joinpath("../test_data/reads_indexable.fa.gz.gzi").as_posix(),
    )
    seq: Sequence = seqs["Record_1"]
    assert seq.id == "Record_1"
    assert seq.desc == "Description 1"
    assert (
        seq.seq
        == "GGGTGATGGCCGCTGCCGATGGCGTCAAATCCCACCAAGTTACCCTTAACAACTTAAGGGTTTTCAAATAGATGCATGCTGATCGATCGTACGATCGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTACCGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGATCGAT"
    )

    seq: Sequence = seqs["Record_2"]
    assert seq.id == "Record_2"
    assert seq.desc == "Description 2"
    assert (
        seq.seq
        == "GTTCAGGGATACGACGTTTGTATTTTAAGAATCCAAGTTACCCTTAACAACTTAAGGGTTTTCAAATAGATGAAGCAGAAGTCGATGATAATACGCGTCGTTTTATCATCAAGTTACCCTTAACAACTTAAGGGTTTTCA"
    )

    seq: Sequence = seqs["Record_7"]
    assert seq.id == "Record_7"
    assert seq.desc == "Description 7"
    assert (
        seq.seq
        == ""
    )
